raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= m <= 3000",
      "description": "The number of players m and the number of top results n are within the specified range."
    },
    {
      "id": "P2",
      "expression": "all(0 <= p <= 2 * m for p in top_points)",
      "description": "Each of the top n points is non-negative and does not exceed twice the number of games."
    },
    {
      "id": "P3",
      "expression": "isinstance(top_points, list) and len(top_points) == n and all(isinstance(p, int) for p in top_points)",
      "description": "The top n points are provided as a list of integers."
    },
    {
      "id": "P4",
      "expression": "all(top_points[i] >= top_points[i + 1] for i in range(n - 1))",
      "description": "The top n points are provided in non-ascending order."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == 'yes' or output == 'no'",
      "description": "The output is either 'yes' or 'no' indicating whether a valid tournament exists."
    },
    {
      "id": "Q2",
      "expression": "output == 'yes'",
      "description": "If there is a valid tournament, the output is 'yes' and the following conditions are met:"
    },
    {
      "id": "Q3",
      "expression": "all(line[i] == 'X' for i, line in enumerate(tournament_table))",
      "description": "The main diagonal is filled with 'X'."
    },
    {
      "id": "Q4",
      "expression": "all(sum(row) == 2 * (m - 1) for row in tournament_table)",
      "description": "Each row in the tournament table has exactly two 'W' entries, indicating a total of 2 points per row."
    },
    {
      "id": "Q5",
      "expression": "all(sum(col) == 2 * (m - 1) for col in zip(*tournament_table))",
      "description": "Each column in the tournament table has exactly two 'W' entries, indicating a total of 2 points per column."
    },
    {
      "id": "Q6",
      "expression": "all(sum(row[i] == 'W' for row in tournament_table) * 2 + sum(row[i] == 'D' for row in tournament_table) == top_points[i] for i in range(n))",
      "description": "The top n rows of the tournament table match the points remembered by Ostap."
    },
    {
      "id": "Q7",
      "expression": "output == 'no' or (output == 'yes' and tournament_table is not None)",
      "description": "If the output is 'no', no tournament table is provided. If the output is 'yes', a valid tournament table is provided."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(tournament_table[i][j] != 'W' for i in range(m) for j in range(m) if i != j)",
      "description": "No player plays against themselves."
    },
    {
      "id": "I2",
      "expression": "all(tournament_table[i][j] != 'L' for i in range(m) for j in range(m) if i != j)",
      "description": "No player loses to themselves."
    },
    {
      "id": "I3",
      "expression": "all(tournament_table[i][j] != 'D' for i in range(m) for j in range(m) if i != j)",
      "description": "No player draws with themselves."
    },
    {
      "id": "I4",
      "expression": "all(tournament_table[i][j] == tournament_table[j][i] for i in range(m) for j in range(m) if i != j)",
      "description": "The tournament table is symmetric."
    }
  ]
}
